import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Physion-Eval: Evaluating Physical Realism in Generated Video via Human Reasoning","description":"","frontmatter":{"title":"Physion-Eval: Evaluating Physical Realism in Generated Video via Human Reasoning","arxiv":"2603.19607","date":"2026-03-20","authors":"Qin Zhang, Peiyu Jing, Hong-Xing Yu, Fangqiang Ding, Fan Nie, Weimin Wang, Yilun Du, James Zou, Jiajun Wu, Bing Shuai","categories":"cs.CV","topics":"物理感知视频生成, 物理真实性评测, 人类标注基准","outline":[2,2]},"headers":[],"relativePath":"papers/2603.19607.md","filePath":"papers/2603.19607.md","lastUpdated":null}'),e={name:"papers/2603.19607.md"};function l(i,s,r,m,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="physion-eval-evaluating-physical-realism-in-generated-video-via-human-reasoning" tabindex="-1">Physion-Eval: Evaluating Physical Realism in Generated Video via Human Reasoning <a class="header-anchor" href="#physion-eval-evaluating-physical-realism-in-generated-video-via-human-reasoning" aria-label="Permalink to &quot;Physion-Eval: Evaluating Physical Realism in Generated Video via Human Reasoning&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2603.19607" target="_blank" rel="noreferrer">2603.19607</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-03-20</td></tr><tr><td><strong>作者</strong></td><td>Qin Zhang, Peiyu Jing, Hong-Xing Yu, Fangqiang Ding, Fan Nie, Weimin Wang, Yilun Du, James Zou, Jiajun Wu, Bing Shuai</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 90 名理工科专家为五个 SOTA 视频模型的 12718 段生成视频打出 10990 条带 0.1 秒级时间戳、故障分类和自然语言解释的推理轨迹，证明 83.3%（第三人称）/ 93.5%（第一人称）的生成视频含至少一处人眼可辨的物理故障，而 MLLM 裁判几乎全部漏检。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型正在被当作 world simulator 用于叙事、仿真和具身 AI 训练。这个用法有一个隐含前提：生成的视频不只是好看，而且要遵守物理规律 —— 物体不能凭空消失，力要产生合理的后果，事件要有因果顺序。但现有的评测基本只回答「像不像真的」，回答不了「<strong>什么时候</strong>、<strong>为什么</strong>这段动力学违反了物理」。</p><p>这个缺口在下游是致命的。如果你用生成视频训练机器人策略，一段「杯子穿过桌面」的视频会给策略注入错误的接触模型，而 FVD 和 CLIP-Score 完全看不出这件事。论文要做的是把「物理真实性」从一个标量偏好分，变成一份带时间戳、带类别、带解释的诊断报告 —— 这样才能反过来指导生成模型的改进。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>VideoPhy / VideoPhy-2、PhyGenBench（PhyGenEval）、PhyWorldBench、PhysBench 这一批工作已经把「评物理」立成了独立问题，做法基本是零样本 MLLM 裁判。论文对它们的批评不是泛泛的「不够准」，而是给出了直接的实验反驳：在本文的设定下，最好的 MLLM 裁判的 Youden&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 只有 19.1%（exocentric）和 9.8%（egocentric），而未经训练的普通观众能拿到 24.9–37.1% 和 48.4–61.8%。也就是说，被广泛用作自动裁判的那个环节，本身就检测不出人眼一眼可见的故障。</p><p>Physics-IQ 和 Morpheus 走的是另一条路 —— 从显著物体的轨迹里提统计量。论文指出这类 object-centric 的形式化天然扩展不到流体、燃烧这些没有主导物体的现象。WorldScore 度量 3D 一致性与光度一致性，但局限于静态场景。</p><p>还有一个被忽略的维度：几乎所有既有评测都只看第三人称视角。第一人称（egocentric）对沉浸式媒体和具身智能恰恰是最关键的，而本文的数据显示这正是模型最弱、MLLM 裁判也最瞎的地方。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>在这篇论文之前，几件事已经清楚了。第一，MLLM 裁判与人类判断的相关性偏弱，这在 Cosmos-Eval 里已有记录。第二，用「偏好」或「打分 rubric」收集的人类反馈信息量太低 —— 你只知道 A 比 B 差，不知道 A 在第 2.3 秒的哪个物体上出了什么错。第三，判断物理合理性需要精确的时空推理，而这恰恰是当前视觉编码器最弱的环节。</p><p>顺着这三点往下推，一个认真的研究者会问：如果我不相信 MLLM 裁判，那 ground truth 从哪来？答案只能是人 —— 但要设计成能产出<strong>结构化诊断</strong>而不只是偏好的形式。于是需要：(i) 一个精心筛选的、每段只含一个清晰物理过程的源视频池（否则多个现象叠加没法归因）；(ii) 一套故障分类法；(iii) 时间戳级的定位；(iv) 自然语言解释。再往下就是标注质量控制的工程问题：怎么保证 90 个人的标注一致。论文的三人工作流（两人独立标注 + 一名资深专家仲裁）是这条链条的自然终点。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>物理错误是<strong>局部的、瞬时的、有明确时刻的</strong>。一个只输出「这段视频物理上合理/不合理」的标量，把这个结构完全压扁了；而一旦你要求标注者说出「第 3.2 秒冰块一边融化一边体积变大」，你就同时拿到了错误位置、错误类型和违反的守恒律。这份结构化信号既能诊断生成器，也能直接当作训练 critic 的监督。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以一段「用液压机压碎物体」的源视频为例：</p><ol><li><strong>源视频筛选</strong>。第三人称来自 WISA-80K（17 类物理现象，覆盖力学、热学、光学）。论文发现原始数据约 <strong>25%</strong> 有质量问题，手工剔除多镜头片段、多物理现象叠加的片段、短于 2 秒的片段、时间倒放的片段（例如水结回冰）、CG/动画内容、带字幕水印的片段、近重复片段、以及物理标签错误的片段（例如汽车行驶被标成「气体运动」）。再做类别平衡，最终留下 <strong>1,734</strong> 段。所有筛选由三名物理博士独立复核。</li><li><strong>第一人称源视频</strong>。从 EPIC-KITCHENS 按动词标签的时间边界切出 4–9 秒片段，得到 <strong>752</strong> 段。动词到物理类别的映射见论文 Table 1（例如 pour/fill/wash → Fluid &amp; Granular Flow，cut/break/crush → Deformation &amp; Fracture）。caption 由 Gemini 2.5 Pro 生成后人工复核。</li><li><strong>生成视频孪生</strong>。以真实视频的 caption + 第一个非全黑帧作为条件，喂给五个 TI2V 模型：Sora 2、Veo 3.1 fast、Kling 2.5、Hailuo 2.3、Wan 2.2。统一中心裁剪到 16:9、缩放到 720×1280、<strong>去掉音轨</strong>。共从 2,486 段真实视频生成 <strong>12,718</strong> 段。</li><li><strong>普通观众研究</strong>。16 名与作者无关联的未训练观众。从 1,500 段源视频里筛出 1,121 段其生成结果含明显物理故障的样本，裁剪到 4–8 秒并<strong>去掉前 20 帧</strong>（消除时长线索和初始化伪影）。每个模型给观众看 100 段第三人称 + 100 段第一人称，真实/生成 1:1 随机混排，同一源片段的真实版和生成版<strong>绝不给同一个观众看</strong>。共收集超过 12,000 次判断。</li><li><strong>专家标注</strong>。90 名 STEM 学士（物理/工程背景），完成六轮培训，按跨标注者一致性和与标准答案的相似度筛出 <strong>38 名资深标注者</strong>。每段视频两人独立标注、一名资深者仲裁。每条最终标注含四要素：故障有无、0.1 秒精度的时间定位、分类标签、自然语言解释。界面支持慢放和精细时间选择。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文只有一处形式化，但它是整个人类研究的度量基础。</p><p>设 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">G</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 分别是真实视频和生成视频的分布，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 表示评估者 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">h</span></span></span></span> 判定视频 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span> 物理上真实。定义两类视频被判为真实的平均比例：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1461em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2491em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mrel mtight">∼</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3567em;margin-left:-0.1389em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1433em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2503em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mclose">)]</span><span class="mord"><span class="delimsizing size1">]</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">G</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mrel mtight">∼</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3567em;margin-left:-0.1389em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">G</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1433em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2503em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mclose">)]</span><span class="mord"><span class="delimsizing size1">]</span></span><span class="mord">.</span></span></span></span></span></p><p>Youden&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 统计量在本文的定义下是二者之差：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1461em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:-0.0962em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">G</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1461em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1461em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">G</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mord">.</span></span></span></span></span></p><p><strong>直觉</strong>：原始的 Youden&#39;s J 是 sensitivity + specificity − 1，用于评估诊断测试。这里被重新诠释为「从真实到生成，被感知为物理真实的比例下降了多少」。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 表示评估者对真实和生成一视同仁（负值截断为 0），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 越大表示生成视频的物理故障造成的感知退化越明显。</p><p>为什么用差值而不是准确率？因为这是一个 <strong>origin-agnostic</strong> 任务，与 deepfake 检测有本质区别：一段合成视频可能物理上完全合理，一段真实视频经过倒放（水结回冰）也会物理上荒谬。论文在附录 §6 专门论证了这一点。用差值可以自动扣掉评估者本身的宽松/严格偏置 —— 一个把所有视频都判为真实的人，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 和 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">G</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 都是 1，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>。</p><p>需要注意的是，这个指标的绝对值依赖于生成视频池的预筛选（本文的池子是<strong>已经筛过、确保含明显故障的</strong>），所以 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 只能在本文的协议内横向比较，不能跨论文比较。论文自己也说这个设计「prioritizes recall」，结果是「conservative upper bounds on perceived physical realism」。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：当前 SOTA 生成的视频，物理故障有多普遍？</strong> 专家标注给出的失败率是：第三人称平均 <strong>83.3%</strong>、第一人称平均 <strong>93.5%</strong>。分模型看（表 2，第三人称/第一人称失败率）：Kling 2.5 为 73.8%/96.4%，Sora 2 为 79.2%/96.6%，Veo 3.1 Fast 为 79.4%/97.5%，Wan 2.2 为 90.3%/83.5%，Hailuo 2.3 为 93.1%/92.0%。故障密度平均每段 1.15–1.92 处，严重度（1–5 分）平均 2.69–3.86。</p><p>一个反直觉的结果被作者点名：<strong>开源的 Wan 2.2 在第一人称设定下无故障视频最多</strong>（失败率 83.5%，是五个模型里最低的），而多个商业模型在这里更差。作者的假设是商业模型优化的是视觉美学和电影感，这在第三人称受益，但在第一人称场景里反而牺牲了物体动力学的稳定性。这是假设，论文没有提供直接证据。</p><p><strong>问题二：普通人能不能看出来？</strong> 能，而且比 MLLM 强得多。普通观众 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 达到 24.9–37.1%（第三人称）、48.4–61.8%（第一人称）。第一人称更容易被看出，作者推测是因为第一人称训练数据少、相机运动更剧烈。</p><p><strong>问题三：MLLM 裁判能替代人吗？</strong> 不能。评测了 10 个模型（GPT-5.2、Gemini 3.0 Pro / 2.5 Pro / 2.5 Flash / 2.5 Flash Lite、Claude Opus 4.5、Qwen3-VL-8B/32B、Cosmos-Reason 1/2），最好的只到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">19.1%</span></span></span></span>（第三人称）和 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">9.8%</span></span></span></span>（第一人称）。关键的诊断是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">G</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>：MLLM 几乎把所有生成视频都判为物理真实，哪怕画面里物体互相穿模。</p><p>两个消融把「加算力能不能救」这条路堵死了。<strong>提高采样帧率无效</strong>：Gemini 3.0 Pro 从 1 FPS 到 10 FPS，第三人称 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 反而从 13.7 掉到 8.1；GPT-5.2 从 12 帧到 48 帧，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 在 2.1–3.2 之间波动。<strong>开启 thinking 无效</strong>：Claude Opus 4.5 和 GPT-5.2 开关思考的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 最大不到 2.0%。作者的解释很有说服力：思考发生在语言空间，如果视觉编码器根本没捕捉到那些细粒度、瞬时的视觉线索，再多推理也无米可炊。</p><p><strong>问题四：故障集中在哪？</strong> 第三人称最常见的是 temporal coherence breakdown 和 material/state inconsistency；第一人称是 temporal coherence breakdown 和 object permanence violation。附录的定性分析进一步指出，失败集中在<strong>接触密集</strong>和<strong>不可逆</strong>的场景 —— 碰撞、材料形变、熵增过程。液压机的例子里模型让物体以不一致的方式压缩、不真实地碎裂、然后又部分恢复原状。低动态场景（燃烧的火焰、日落）则生成得相当好。</p><p>需要指出一处数值口径差异：正文 §4.1.2 给出人类 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 的<strong>范围</strong>是 24.9–37.1%（第三人称）、48.4–61.8%（第一人称），而附录表 3、表 4 里的「Human (reference)」用的是具体模型子集上的值（24.9 / 58.5），两者口径不同，比较时需注意。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：Physion-Eval 用 90 名理工科专家、三人仲裁工作流，为五个 SOTA 视频模型的 12,718 段生成视频产出了 10,990 条带 0.1 秒时间戳、故障分类和自然语言解释的推理轨迹，覆盖 22 类物理现象和第一/第三人称双视角。结果是 83.3%（第三人称）和 93.5%（第一人称）的生成视频含至少一处人眼可辨的物理故障。未训练的普通观众能可靠检测这些故障，而 10 个 SOTA MLLM 裁判几乎全部漏检，且提高帧率或开启 thinking 都救不回来。故障集中在接触密集与不可逆过程，第一人称尤其糟糕。这份数据的主要价值不在于排名，而在于它能直接训练一个会定位、会解释的物理 critic。</p><p><strong>3 句话版</strong>：当前最好的视频生成模型，在物理关键场景里九成左右的输出都有人眼可见的物理错误。被广泛用作自动评测的 MLLM 裁判基本检测不出这些错误，且这不是算力问题而是视觉编码问题。Physion-Eval 把人类专家的诊断推理固化成了带时间戳的结构化数据。</p><p><strong>1 句话版</strong>：别再用 MLLM 当物理裁判了 —— 它连普通人一眼能看出的穿模都判不出来。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>人类专家的知觉判断可以充当物理真实性的 ground truth</strong>。整篇论文的所有结论 —— 包括「MLLM 裁判失效」这个最重要的 claim —— 都以人类标注为参照系。</p><p>它可能不成立的原因在于，人类的物理直觉本身是<strong>系统性有偏</strong>的。认知科学里有大量记录：人对抛体轨迹、角动量、流体粘度的直觉判断存在稳定的错误模式（例如「冲量理论」式的直觉，认为物体运动需要持续的力）。这意味着一段<strong>物理上正确但违反人类直觉</strong>的生成视频会被判为故障，而一段<strong>符合直觉但物理错误</strong>的视频会被漏过。论文自己在 limitations 里承认评测「依赖可视线索，力、能量、熵这类隐变量只能间接推断」，并承认「判断本身具有主观性」。</p><p>论文为这个假设提供的证据是：六轮培训、按一致性筛出 38 名资深标注者、两标一裁的仲裁流程。<strong>缺失的证据</strong>是标注者间一致性的具体数值（如 Cohen&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span> 或 Krippendorff&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span>）—— 论文说用一致性做了质量监控，但没有报告最终标注的 agreement 统计量。同样缺失的是把标注与<strong>可验证的物理真值</strong>对照的校准实验：例如用真实的物理仿真渲染一批已知违反某条守恒律的视频，看专家能否检出、检出率多少。没有这一环，「专家标注 = ground truth」就只是一个基于资质的假设，而不是被检验过的结论。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、不需要重建整个标注流水线：</p><ul><li><strong>数据</strong>：从 Physion-Eval 的 HuggingFace 仓库取 200 段带专家标注的生成视频（100 第三人称 + 100 第一人称），及其对应的真实源视频。</li><li><strong>实现</strong>：只复现 MLLM 裁判部分。用两个模型（一个开源如 Qwen3-VL-32B、一个 API 模型），套用论文附录 §8 给出的完整 prompt，输出 REALISTIC/UNREALISTIC 标签。</li><li><strong>测量</strong>：按公式 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">G</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 计算，与论文报告的量级对照。同时额外测一个论文没做的对照：<strong>把 prompt 换成&quot;这段视频里有几个物体？&quot;这类纯感知问题</strong>，检验模型在同一批视频上的基础视觉能力。</li><li><strong>判据</strong>：如果复现出的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 落在 0–20% 区间且远低于论文报告的人类值，支持论文的核心 claim。如果模型在纯感知问题上也很差，那「MLLM 缺的是物理推理」这个解释就要让位给「MLLM 在这批 720×1280 短视频上的基础视觉就不行」，这会改变论文的归因。</li></ul><p>成本主要是 API 调用，不需要 GPU 训练。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是给 MLLM 的低 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span> 提供一个<strong>替代解释</strong>：MLLM 不是「看不出物理错误」，而是被 <strong>prompt 与决策阈值</strong>系统性地推向了「realistic」这一侧。</p><p>支持这个替代解释的证据就在论文里：作者观察到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">G</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>，即 MLLM 几乎把所有生成视频都判为真实。但论文给 MLLM 的 prompt（附录 §8）明确写着「Be conservative when evidence is ambiguous」—— 这是一条**要求模型倾向于判&quot;合理&quot;**的指令。而人类观众拿到的指示是「若未观察到明显故障则标为 realistic」，措辞上同样偏向宽松，但人类不会像 LLM 那样对指令中的「conservative」过度敏感。换句话说，人类和 MLLM 拿到的不是同一个决策阈值。</p><p>具体的反例实验分三步。第一步，把 MLLM 的输出从二分类改成<strong>连续的 confidence 分数</strong>（prompt 里已经要求输出 confidence 0–100），然后扫描阈值画 ROC 曲线，报告 AUC 而非固定阈值下的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span>。如果 AUC 显著高于 0.5，说明模型内部<strong>有</strong>判别信号，只是阈值错了，那「MLLM 检测不出物理错误」就应该被改写成「MLLM 的校准坏了」—— 这是一个工程上容易修的问题，结论的严重性大幅下降。第二步，把 prompt 里的「be conservative」删掉，或换成强制配额（「这批视频中约一半含故障，请标出故障的那些」），重测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span>。第三步，做一个人类对照组，给他们和 MLLM <strong>完全相同</strong>的 prompt 文本。</p><p>如果三步下来 MLLM 的 AUC 依然接近随机、且强制配额也无法提升，论文的结论就非常扎实。反之，论文报告的巨大差距里有相当一部分是协议不对称造成的。论文做了 thinking 和帧率的消融，但<strong>没有做阈值/校准的消融</strong>，这是我认为它最应该补的实验。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：Physion-Eval 的标注是<strong>离线的、被动的</strong>。标注者看完一段视频，指出第 3.2 秒有问题。但这条信息无法回答一个更有用的问题：「如果生成器在第 3.2 秒之前的某个决策不同，这个错误会不会消失？」也就是说，数据记录了故障的<strong>症状</strong>，没有记录故障的<strong>可干预点</strong>。这限制了它能训出来的 critic —— 一个只会说「这里错了」的 critic，给生成器的梯度信号非常弱。</p><p><strong>(b) 可借鉴的相邻领域工具</strong>：因果推断里的<strong>反事实介入</strong>，以及软件工程里的 <strong>delta debugging</strong>。核心思路是把物理故障的定位从「时间轴上的一个点」重新 framing 为「生成轨迹上的一个分叉点」：对同一个 prompt 和首帧，用不同随机种子生成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 条轨迹，让专家标注每条的故障时刻，然后在 latent 空间里做二分搜索，找到<strong>最早的那个 latent 状态</strong>，使得从它出发的所有 rollout 都必然导向故障。这就把症状标注升级成了责任归因。</p><p><strong>(c) 第一个实验</strong>：选 Physion-Eval 里失败率最高的一个类别（第一人称的 object permanence violation），用 Wan 2.2（开源、可访问中间 latent）对 50 个 prompt 各生成 16 条轨迹。用 Physion-Eval 训出的 critic 自动标注每条轨迹的首个故障时刻，然后测量：故障时刻的分布是否呈现<strong>明显的分叉结构</strong>（即在某个去噪步之前所有轨迹都还正常，之后迅速分化）。如果是，就说明存在可干预的关键步，下一步可以在那些步上做 guidance；如果故障时刻均匀分布在整条轨迹上，那说明物理错误是弥散的、无法通过局部干预修复，这本身也是一个重要的负面结论 —— 它会告诉整个领域，靠后处理和 guidance 修物理是死路，必须改训练目标。</p>',56)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
